	public static void refreshQuerySafetySnapshot(QueryModelNode changedNode) {
		QuerySafetySnapshot active = ACTIVE_SAFETY_SNAPSHOT.get();
		if (active != null && changedNode != null) {
			active.refreshFrom(changedNode);
		}
	}

	private static QuerySafetySnapshot snapshotFor(QueryModelNode node) {
		QuerySafetySnapshot active = ACTIVE_SAFETY_SNAPSHOT.get();
		if (active == null) {
			return querySafetySnapshot(node);
		}
		active.ensureNode(node);
		return active;
	}

	/**
	 * Pins function implementations and classifies the resulting subtree within one atomic preparation step.
	 */
	@Experimental
	public static boolean isRepeatableWithinPreparation(QueryModelNode node) {
		return isRepeatable(pinFunctions(node));
	}

	/**
	 * Atomically captures every function implementation referenced by a query subtree. Captured calls retain only the
	 * function instance (or its absence), so later registry replacement cannot invalidate optimizer decisions.
	 */
	@Experimental
	@SuppressWarnings("unchecked")
	public static <T extends QueryModelNode> T pinFunctions(T node) {
		FunctionRegistry registry = FunctionRegistry.getInstance();
		synchronized (registry) {
			FunctionPinningVisitor visitor = new FunctionPinningVisitor(registry);
			if (node instanceof FunctionCall && !(node instanceof PinnedFunctionCall)) {
				Function function = registry.get(((FunctionCall) node).getURI()).orElse(null);
				if (function == null || !isRepeatable(function)) {
					node.visit(visitor);
					return node;
				}
				PinnedFunctionCall pinned = new PinnedFunctionCall((FunctionCall) node, function);
				if (node.getParentNode() != null) {
					node.replaceWith(pinned);
				}
				pinned.visit(visitor);
				return (T) pinned;
			}
			node.visit(visitor);
			return node;
		}
	}

	/** Returns the implementation pinned for this call, or the current registry entry for an unpinned call. */
	@Experimental
	public static Optional<Function> resolveFunction(FunctionCall node) {
		if (node instanceof PinnedFunctionCall) {
			PinnedFunctionCall pinned = (PinnedFunctionCall) node;
			Function function = pinned.function;
			if (function != null) {
				return Optional.of(function);
			}
			Function registered = FunctionRegistry.getInstance().get(node.getURI()).orElse(null);
			if (registered != null && registered.getClass() == pinned.functionClass) {
				pinned.function = registered;
				return Optional.of(registered);
			}
			return Optional.empty();
		}
		return FunctionRegistry.getInstance().get(node.getURI());
	}

	/**
	 * Returns whether a resolved function implementation is stable within one query execution: equal argument tuples
	 * produce equal RDF terms or equivalent errors, so the optimizer may collapse equal expressions and re-evaluate
	 * calls with equal arguments. True for exact whitelisted builtin classes, for RDF4J's query-constant NOW
	 * implementation, and for third-party functions that declare {@link Function.Determinism#DETERMINISTIC}. A
	 * {@link Function#mustReturnDifferentResult() must-differ} freshness guarantee dominates any declaration.
	 */
	@Experimental
	public static boolean isRepeatable(Function function) {
		return isRepeatable(function, activePolicy());
	}

	/**
	 * Returns whether a resolved function implementation is stable within one query execution under the given policy. A
	 * function of {@link Function.Determinism#UNSPECIFIED unspecified} determinism is repeatable under the default
	 * policy (the long-standing planning for third-party functions) and a conservative barrier under the experimental
	 * query optimizations profile; an explicit {@link Function.Determinism#VOLATILE} declaration is a barrier under
	 * both.
	 */
	@Experimental
	public static boolean isRepeatable(Function function, QueryExecutionPolicy policy) {
		if (function.mustReturnDifferentResult()) {
			return false;
		}
		return isQueryStable(function) || DETERMINISTIC_FUNCTION_CLASSES.contains(function.getClass())
				|| isDeclaredRepeatable(function, policy);
	}

	/**
	 * Returns whether a resolved function implementation may be constant-folded into a REUSABLE prepared query plan.
	 * This is strictly stronger than {@link #isRepeatable(Function)}: a prepared plan can be executed repeatedly, so
	 * only functions that are immutable across executions qualify. RDF4J's query-constant NOW is deliberately excluded
	 * — its per-execution value is handled by a dedicated evaluation path with a fresh scope per execution.
	 */
	@Experimental
	public static boolean isSafeForPlanConstantFolding(Function function) {
		return isSafeForPlanConstantFolding(function, activePolicy());
	}

	/**
	 * Returns whether a resolved function implementation may be constant-folded into a reusable prepared plan under the
	 * given policy. Unspecified determinism folds under the default policy and never under the experimental profile;
	 * see {@link #isRepeatable(Function, QueryExecutionPolicy)}.
	 */
	@Experimental
	public static boolean isSafeForPlanConstantFolding(Function function, QueryExecutionPolicy policy) {
		if (function.mustReturnDifferentResult() || isQueryStable(function)) {
			return false;
		}
		return DETERMINISTIC_FUNCTION_CLASSES.contains(function.getClass())
				|| isDeclaredRepeatable(function, policy);
	}

	private static boolean isDeclaredRepeatable(Function function, QueryExecutionPolicy policy) {
		Function.Determinism determinism = function.getDeterminism();
		if (determinism == Function.Determinism.DETERMINISTIC) {
			return true;
		}
		return determinism == Function.Determinism.UNSPECIFIED
				&& !Objects.requireNonNull(policy, "policy must not be null").experimentalQueryOptimizations();
	}

	/**
	 * Returns whether a resolved function is RDF4J's query-constant NOW implementation.
	 */
	private static boolean isQueryStable(Function function) {
		return function.getClass() == Now.class;
	}

	/**
	 * Returns whether a query-model subtree may raise an error that fails the whole query rather than a single
	 * solution. Ordinary expression errors are row-local (a BIND error leaves the target variable unbound, a FILTER
	 * error drops the solution, an ORDER expression error sorts as an unbound value); a failed non-silent SERVICE
	 * invocation is an error for the whole query, and unknown tuple-expression extensions are conservatively assumed
	 * capable of the same.
	 */
	@Experimental
	public static boolean mayRaiseQueryFatalError(QueryModelNode subtree) {
		return snapshotFor(subtree).mayRaiseQueryFatalError(subtree);
	}

	/**
	 * Returns whether a subtree may be discarded without ever being evaluated — for example because a sibling join
	 * operand is empty, a condition is statically false, or a physical strategy short-circuits — without suppressing an
	 * observable query-fatal error. Whether a query fails or returns a (possibly empty) result is observable SPARQL
	 * behavior: the formal algebra evaluates each operand, so a discarded operand's non-silent SERVICE failure must
	 * still surface.
	 */
	@Experimental
	public static boolean canDiscardWithoutEvaluation(QueryModelNode subtree) {
		return !snapshotFor(subtree).mayRaiseQueryFatalError(subtree);
	}

	/**
	 * Returns whether pushing the given set of bindings into the subtree as evaluation-time input is proven equivalent
	 * to evaluating the subtree independently and applying a compatible-mapping join afterwards (the binding-injection
	 * contract behind physical bind joins). Injection safety is a JOINT property of the injected set, not a
	 * per-variable one: {@code FILTER(!BOUND(?x) || !BOUND(?y))} is safe for {?x} alone and for {?y} alone but not for
	 * {?x,?y} — so callers must ask about the exact set they intend to inject and must never union per-variable
	 * answers. This initial analysis is conservative: it permits injection only into positive pattern shapes (statement
	 * patterns, joins, unions, nested optionals, VALUES) where injected names act purely as pattern-variable
	 * selections, and rejects the subtree outright when any expression reads an injected name that the subtree does not
	 * assuredly bind, when any BIND target collides with one (an {@code Extend} whose target is pre-bound is undefined
	 * in the algebra and RDF4J's evaluation would overwrite it), and for mapping-parameterized operators such as
	 * property paths, whose seeded evaluation observably differs from independent evaluation (see
	 * {@link #usesMappingParameterizedEvaluation(TupleExpr)}). Every conservative rejection is a candidate for later
	 * refinement, not a semantic claim.
	 */
	@Experimental
	public static boolean permitsBindingInjection(TupleExpr subtree, Set<String> injectedNames) {
		if (injectedNames.isEmpty()) {
			return true;
		}
		return snapshotFor(subtree).permitsBindingInjection(subtree, injectedNames);
	}

